29	/**
30	 * Convenient base implementation for {@link Permalink}s that satisfy
31	 * certain properties.
32	 *
33	 * <p>
34	 * For a permalink to be able to use this, it has to satisfy the following:
35	 *
36	 * <blockquote>
37	 *     Given a job J, permalink is a function F that computes a build B.
38	 *     A peephole permalink is a subset of this function that can be
39	 *     deduced to the "peep-hole" function G(B)→bool:
40	 *
41	 *     <pre>
42	 *         F(J) = { newest B | G(B)==true }
43	 *     </pre>
44	 * </blockquote>
45	 *
46	 * <p>
47	 * Intuitively speaking, a peep-hole permalink resolves to the latest build that
48	 * satisfies a certain characteristics that can be determined solely by looking
49	 * at the build and nothing else (most commonly its build result.)
50	 *
51	 * <p>
52	 * This base class provides a file-based caching mechanism that avoids
53	 * walking the long build history.
54	 *
55	 * <p>
56	 * The implementation transparently tolerates G(B) that goes from true to false over time
57	 * (it simply scans the history till find the new matching build.) To tolerate G(B)
58	 * that goes from false to true, you need to be able to intercept whenever G(B) changes
59	 * from false to true, then call {@link #resolve(Job)} to check the current permalink target
60	 * is up to date, then call {@link #updateCache(Job, Run)} if it needs updating.
61	 *
62	 * @since 1.507
63	 */
64	public abstract class PeepholePermalink extends Permalink implements Predicate<Run<?, ?>> {
65	
66	    /**
67	     * JENKINS-22822: avoids rereading caches.
68	     * Top map keys are {@code builds} directories.
69	     * Inner maps are from permalink name to build number.
70	     * Synchronization is first on the outer map, then on the inner.
71	     */
72	    private static final Map<File, Map<String, Integer>> caches = new HashMap<>();
73	
74	    /**
75	     * Checks if the given build satisfies the peep-hole criteria.
76	     *
77	     * This is the "G(B)" as described in the class javadoc.
78	     */
79	    public abstract boolean apply(Run<?, ?> run);
80	
81	    @Override
82	    public boolean test(Run<?, ?> run) {
83	        return apply(run);
84	    }
85	
86	    /** @deprecated No longer used. */
87	    @Deprecated
88	    protected File getPermalinkFile(Job<?, ?> job) {
89	        return new File(job.getBuildDir(), getId());
90	    }
91	
92	    /**
93	     * Resolves the permalink by using the cache if possible.
94	     */
95	    @Override
96	    public Run<?, ?> resolve(Job<?, ?> job) {
97	        Map<String, Integer> cache = cacheFor(job.getBuildDir());
98	        int n;
99	        synchronized (cache) {
100	            n = cache.getOrDefault(getId(), 0);
101	        }
102	        if (n == RESOLVES_TO_NONE) {
103	            return null;
104	        }
105	        Run<?, ?> b;
106	        if (n > 0) {
107	            b = job.getBuildByNumber(n);
108	            if (b != null && apply(b)) {
109	                return b; // found it (in the most efficient way possible)
110	            }
111	        } else {
112	            b = null;
113	        }
114	
115	        // the cache is stale. start the search
116	        if (b == null) {
117	            b = job.getNearestOldBuild(n);
118	        }
119	
120	        if (b == null) {
121	            // no cache
122	            b = job.getLastBuild();
123	        }
124	
125	        // start from the build 'b' and locate the build that matches the criteria going back in time
126	        b = find(b);
127	
128	        updateCache(job, b);
129	        return b;
130	    }
131	
132	    /**
133	     * Start from the build 'b' and locate the build that matches the criteria going back in time
134	     */
135	    private Run<?, ?> find(Run<?, ?> b) {
136	        //noinspection StatementWithEmptyBody
137	        for ( ; b != null && !apply(b); b = b.getPreviousBuild())
138	            ;
139	        return b;
140	    }
141	
142	    private static @NonNull Map<String, Integer> cacheFor(@NonNull File buildDir) {
143	        synchronized (caches) {
144	            Map<String, Integer> cache = caches.get(buildDir);
145	            if (cache == null) {
146	                cache = load(buildDir);
147	                caches.put(buildDir, cache);
148	            }
149	            return cache;
150	        }
151	    }
152	
153	    private static @NonNull Map<String, Integer> load(@NonNull File buildDir) {
154	        Map<String, Integer> cache = new TreeMap<>();
155	        File storage = storageFor(buildDir);
156	        if (storage.isFile()) {
157	            try (Stream<String> lines = Files.lines(storage.toPath(), StandardCharsets.UTF_8)) {
158	                lines.forEach(line -> {
159	                    int idx = line.indexOf(' ');
160	                    if (idx == -1) {
161	                        return;
162	                    }
163	                    try {
164	                        cache.put(line.substring(0, idx), Integer.parseInt(line.substring(idx + 1)));
165	                    } catch (NumberFormatException x) {
166	                        LOGGER.log(Level.WARNING, "failed to read " + storage, x);
167	                    }
168	                });
169	            } catch (IOException x) {
170	                LOGGER.log(Level.WARNING, "failed to read " + storage, x);
171	            }
172	            LOGGER.fine(() -> "loading from " + storage + ": " + cache);
173	        }
174	        return cache;
175	    }
176	
177	    static @NonNull File storageFor(@NonNull File buildDir) {
178	        return new File(buildDir, "permalinks");
179	    }
180	
181	    /**
182	     * Remembers the value 'n' in the cache for future {@link #resolve(Job)}.
183	     */
184	    protected void updateCache(@NonNull Job<?, ?> job, @CheckForNull Run<?, ?> b) {
185	        File buildDir = job.getBuildDir();
186	        Map<String, Integer> cache = cacheFor(buildDir);
187	        synchronized (cache) {
188	            cache.put(getId(), b == null ? RESOLVES_TO_NONE : b.getNumber());
189	            File storage = storageFor(buildDir);
190	            LOGGER.fine(() -> "saving to " + storage + ": " + cache);
191	            try (AtomicFileWriter cw = new AtomicFileWriter(storage)) {
192	                try {
193	                    for (Map.Entry<String, Integer> entry : cache.entrySet()) {
194	                        cw.write(entry.getKey());
195	                        cw.write(' ');
196	                        cw.write(Integer.toString(entry.getValue()));
197	                        cw.write('\n');
198	                    }
199	                    cw.commit();
200	                } finally {
201	                    cw.abort();
202	                }
203	            } catch (IOException x) {
204	                LOGGER.log(Level.WARNING, "failed to update " + storage, x);
205	            }
206	        }
207	    }
