209	    @Extension
210	    public static class RunListenerImpl extends RunListener<Run<?, ?>> {
211	        /**
212	         * If any of the peephole permalink points to the build to be deleted, update it to point to the new location.
213	         */
214	        @Override
215	        public void onDeleted(Run run) {
216	            Job<?, ?> j = run.getParent();
217	            for (PeepholePermalink pp : Util.filter(j.getPermalinks(), PeepholePermalink.class)) {
218	                if (pp.resolve(j) == run) {
219	                    Run<?, ?> r = pp.find(run.getPreviousBuild());
220	                    LOGGER.fine(() -> "Updating " + pp.getId() + " permalink from deleted " + run + " to " + (r == null ? -1 : r.getNumber()));
221	                    pp.updateCache(j, r);
222	                }
223	            }
224	        }
225	
226	        /**
227	         * See if the new build matches any of the peephole permalink.
228	         */
229	        @Override
230	        public void onCompleted(Run<?, ?> run, @NonNull TaskListener listener) {
231	            Job<?, ?> j = run.getParent();
232	            for (PeepholePermalink pp : Util.filter(j.getPermalinks(), PeepholePermalink.class)) {
233	                if (pp.apply(run)) {
234	                    Run<?, ?> cur = pp.resolve(j);
235	                    if (cur == null || cur.getNumber() < run.getNumber()) {
236	                        LOGGER.fine(() -> "Updating " + pp.getId() + " permalink to completed " + run);
237	                        pp.updateCache(j, run);
238	                    }
239	                }
240	            }
241	        }
242	    }
